import React, { useState } from 'react';
import Popup from './Popup';

const departmentForms = {
    survey: [
        { label: 'Type of Survey', name: 'typeOfArea' },
        { label: 'Khasra No', name: 'khasraNo' },
        { label: 'Area', name: 'Area' },
        { label: 'Demarcation', name: 'demarcation' },
        { label: 'Day in Survey', name: 'dayinsurvey' },
        { label: 'Total Cost', name: 'totalCost' },
        { label: 'Remarks', name: 'remarks' }
    ],
    architecture: [
        { label: 'Type Of Architectural', name: 'tyopeofarchitectural' },
        { label: 'Demarcation', name: 'demarcation' },
        { label: 'Area', name: 'Area' },
        { label: 'Total Cost', name: 'totalcost' },
        { label: 'Remarks', name: 'remarks' }
    ],
    urbanPlanning: [
        { label: 'Area', name: 'Area' },
        { label: 'Khasra No', name: 'khasraNo' },
        { label: 'Demarcation', name: 'demarcation' },
        { label: 'Total Cost', name: 'totalCost' },
        { label: 'Remarks', name: 'remarks' }
    ],
    EngineeringDrawing: [
        { label: 'Area', name: 'Area' },
        { label: 'Khasra No', name: 'khasraNo' },
        { label: 'Total Cost', name: 'totalCost' },
        { label: 'Remarks', name: 'remarks' }
    ],
    JDASubmission: [
        { label: 'Area', name: 'Area' },
        { label: 'Khasra No', name: 'khasraNo' },
        { label: 'Total Cost', name: 'totalCost' },
        { label: 'Remarks', name: 'remarks' }
    ],
    GIS: [
        { label: 'Name of Scheme', name: 'nameofscheme' },
        { label: 'Khasra No', name: 'khasraNo' },
        { label: 'Area', name: 'Area' },
        { label: 'Total Cost', name: 'totalCost' },
        { label: 'Remarks', name: 'remarks' }
    ],
    SitePlan: [
        { label: 'Number Of Plots', name: 'numofplots' },
        { label: 'Khasra No', name: 'khasraNo' },
        { label: 'Number of Plots', name: 'numofplots' },
        { label: 'Total Cost', name: 'totalCost' },
        { label: 'Remarks', name: 'remarks' }
    ],
    AreaConversion: [
        { label: 'Area', name: 'Area' },
        { label: 'Khasra No', name: 'khasraNo' },
        { label: 'Total Cost', name: 'totalCost' },
        { label: 'Remarks', name: 'remarks' }
    ],
    SectorSuperImpose: [
        { label: 'Khasra No', name: 'khasraNo' },
        { label: 'Total Cost', name: 'totalCost' },
        { label: 'Remarks', name: 'remarks' }
    ],
    Print: [
        { label: 'Type of Print', name: 'typeofprint' },
        { label: 'Khasra No', name: 'khasraNo' },
        { label: 'Paper Size', name: 'papersize' },
        { label: 'Total Cost', name: 'totalcost' },
        { label: 'Remarks', name: 'remarks' }
    ],
    // Add more departments with their own unique fields as needed
};

const FormComponent = ({ selectedDepartment }) => {
    const [formData, setFormData] = useState({});
    const [showPopup, setShowPopup] = useState(false);

    // Handle form input change
    const handleChange = (e) => {
        const { name, value } = e.target;
        setFormData((prevData) => ({
            ...prevData,
            [name]: value
        }));
    };

    // Handle submit button click
    const handleSubmit = (e) => {
        e.preventDefault();
        setShowPopup(true);
    };

    // Confirm the submission
    const handleConfirm = () => {
        alert('Form Submitted!');
        setShowPopup(false);
        // Add form submission logic here (e.g., API call)
    };

    // Cancel the popup and reset
    const handleCancel = () => {
        setShowPopup(false);
    };

    const departmentFields = departmentForms[selectedDepartment] || [];

    return (
        <div>
            <form onSubmit={handleSubmit}>
                <div className="form-container">
                    {departmentFields.map((field, index) => (
                        <div key={index}>
                            <label>{field.label}:</label>
                            <input
                                type="text"
                                name={field.name}
                                value={formData[field.name] || ''}
                                onChange={handleChange}
                            />
                        </div>
                    ))}
                    <button type="submit">Submit</button>
                </div>
            </form>

            {showPopup && (
                <Popup
                    formData={formData}
                    onConfirm={handleConfirm}
                    onCancel={handleCancel}
                />
            )}
        </div>
    );
};

export default FormComponent;
